const failures = $input.all().map(i => i.json);
const toEscalate = failures.filter(f => {
  if (f.severity === 'critical' && f.minutesSinceCreated >= 120 && f.notificationsSent < 2) return true;
  if (f.severity === 'high' && f.minutesSinceCreated >= 240 && f.notificationsSent < 1) return true;
  return false;
});
return toEscalate.map(f => ({ json: f }));

const items = $input.all();
const criticalItems = items.filter(i => i.json.severity === 'critical');
const highItems = items.filter(i => i.json.severity === 'high');

let html = '<h2>⚠️ Escalation Alert — Unacknowledged Failures</h2>';
html += '<p>The following failures have not been acknowledged within the required time window:</p>';

if (criticalItems.length > 0) {
  html += '<h3 style="color:red">🔴 Critical (>2 hours unacknowledged)</h3><ul>';
  criticalItems.forEach(i => {
    const f = i.json;
    html += `<li><b>${f.rigName}</b> — ${f.title || f.description?.slice(0,80)} (${f.minutesSinceCreated} min ago)<br><a href="https://rigmind.aquila-engineer.com/failures/${f.id}">View & Acknowledge →</a></li>`;
  });
  html += '</ul>';
}

if (highItems.length > 0) {
  html += '<h3 style="color:orange">🟠 High (>4 hours unacknowledged)</h3><ul>';
  highItems.forEach(i => {
    const f = i.json;
    html += `<li><b>${f.rigName}</b> — ${f.title || f.description?.slice(0,80)} (${f.minutesSinceCreated} min ago)<br><a href="https://rigmind.aquila-engineer.com/failures/${f.id}">View & Acknowledge →</a></li>`;
  });
  html += '</ul>';
}

return [{ json: {
  emailBody: html,
  subject: `🚨 ESCALATION: ${criticalItems.length} Critical, ${highItems.length} High failures unacknowledged — ACTION REQUIRED`,
  criticalCount: criticalItems.length,
  highCount: highItems.length,
  totalCount: items.length
}}];
